  for (const d of dead) {
    const { id, error, ...data } = d.data;
    await jobs.add(\"notification\", data, {
      jobId: \"replay-\" + id,
      attempts: 3,
      backoff: { type: \"fixed\", delay: 200 },
      removeOnComplete: 5000,
