    n++;
    console.log(\"requeued\", n, id);
    await sleep(2000);
  }
  await jobs.close(); await dlq.close(); await conn.quit();
  console.log(\"done\", n);
})().catch((e) => { console.error(\"ERR\", e); process.exit(1); });
EOF
