const fs = require(\"fs\");
const path = require(\"path\");
const config = require(\"./config\");

const LEVELS = { debug: 10, info: 20, warn: 30, error: 40 };
const threshold = LEVELS[config.logLevel] || LEVELS.info;
const LOG_FILE = path.join(config.logDir, \"app.log\");
const MAX_FILE_BYTES = 64 * 1024;

fs.mkdirSync(config.logDir, { recursive: true });

let fileBytes = 0;
try {
  fileBytes = fs.statSync(LOG_FILE).size;
} catch (err) {
  fileBytes = 0;
}

function writeFile(line) {
  try {
    const size = Buffer.byteLength(line);
    if (fileBytes + size > MAX_FILE_BYTES) {
      fs.truncateSync(LOG_FILE, 0);
      fileBytes = 0;
    }
    fs.appendFileSync(LOG_FILE, line);
    fileBytes += size;
  } catch (err) {
    fileBytes = MAX_FILE_BYTES;
  }
}

function write(level, msg, fields = {}) {
  if (LEVELS[level] < threshold) return;
  const line = JSON.stringify({ ts: new Date().toISOString(), level, msg, ...fields }) + \"\\n\";
  writeFile(line);
  if (level "'!== "debug") process.stdout.write(line);
}

module.exports = {
  debug: (msg, fields) => write("debug", msg, fields),
  info: (msg, fields) => write("info", msg, fields),
  warn: (msg, fields) => write("warn", msg, fields),
  error: (msg, fields) => write("error", msg, fields),
};
EOF
