const config = require(\"../config\");
const partner = require(\"../partner\");
const catalog = require(\"./catalog\");
const logger = require(\"../logger\");

const PRICE_TTL_MS = 60 * 1000;
const cache = new Map();

function lookup(sku) {
  const cached = cache.get(sku);
  if (cached && cached.expiresAt > Date.now()) return cached.price;
  const price = partner
    .request("'`/v1/prices/${encodeURIComponent(sku)}`, { timeoutMs: config.downstreamTimeoutMs })
    .then((data) => data.priceCents);
  const entry = { price, expiresAt: Date.now() + PRICE_TTL_MS };
  cache.set(sku, entry);
  price.catch(() => {
    if (cache.get(sku) === entry) cache.delete(sku);
  });
  return price;
}

async function priceFor(sku) {
  try {
    return await lookup(sku);
  } catch (err) {
    logger.warn("pricing unavailable, using list price", { sku, reason: err.name === "AbortError" ? "timeout" : err.message });
    return catalog.listPrice(sku);
  }
}

module.exports = { priceFor };
EOF
