const config = require(\"../config\");
const partner = require(\"../partner\");
const logger = require(\"../logger\");

const MAX_RATE_LIMIT_RETRIES = 5;
const BASE_DELAY_MS = 1000;
const MAX_DELAY_MS = 15000;

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

function rateLimitDelay(err, attempt) {
  if (err.retryAfterSec > 0) return Math.min(err.retryAfterSec * 1000, MAX_DELAY_MS);
  const backoff = Math.min(BASE_DELAY_MS * 2 ** attempt, MAX_DELAY_MS);
  return backoff / 2 + Math.random() * (backoff / 2);
}

async function send({ notificationId, userId, message }) {
  for (let attempt = 0; ; attempt++) {
