      });
    } catch (err) {
      if (err.status "'!== 429 || attempt >= MAX_RATE_LIMIT_RETRIES) throw err;
      const delayMs = rateLimitDelay(err, attempt);
      logger.warn("partner rate limited notification, retrying", { notificationId, attempt: attempt + 1, delayMs });
      await sleep(delayMs);
    }
  }
}

module.exports = { send };
