const logger = require(\"../logger\");

const PRICE_CACHE_TTL_MS = 5 * 60 * 1000;
const MAX_PRICE_TIMEOUT_MS = 5000;
const cache = new Map();

async function priceFor(sku) {
  const cached = cache.get(sku);
  if (cached && cached.expiresAt > Date.now()) return cached.priceCents;
  try {
    const data = await partner.request("'`/v1/prices/${encodeURIComponent(sku)}`, {
