    return data.priceCents;
  } catch (err) {
    logger.warn("pricing unavailable, using list price", { sku, reason: err.name === "AbortError" ? "timeout" : err.message });
    return catalog.listPrice(sku);
  }
}

module.exports = { priceFor };
